.ds-query-tool:has(.ds-query-suggestions[open]) {
  width: auto;
}

.ds-query-tool .ds-query-help.ds-query-suggestions,
.ds-query-tool .ds-query-help.ds-query-suggestions[open] {
  position: relative;
  top: auto;
  right: auto;
  width: auto;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.ds-query-tool .ds-query-help.ds-query-suggestions > summary {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 40px;
  min-width: 40px;
  height: 40px;
  min-height: 40px;
  padding: 0;
  border-radius: var(--radius-pill);
  list-style: none;
  color: var(--muted);
  transition:
    background 160ms var(--ease),
    color 160ms var(--ease);
}

.ds-query-tool .ds-query-help.ds-query-suggestions > summary::-webkit-details-marker {
  display: none;
}

.ds-query-tool .ds-query-help.ds-query-suggestions > summary:hover,
.ds-query-tool .ds-query-help.ds-query-suggestions[open] > summary {
  background: var(--soft);
  color: var(--accent);
}

.ds-query-tool .ds-query-help.ds-query-suggestions > summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.ds-query-tool .ds-query-suggestions > .ds-query-suggestions-panel {
  position: absolute;
  z-index: 12;
  top: calc(100% + 10px);
  right: 0;
  display: block;
  width: min(368px, calc(100vw - 36px));
  overflow: hidden;
  padding: 16px 8px 0;
  border-radius: 14px;
  color: var(--ink);
  background: var(--canvas);
  box-shadow: 0 12px 36px color-mix(in srgb, var(--ink) 16%, transparent);
}

.ds-query-suggestions .ds-query-suggestions-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 0 8px;
}

.ds-query-suggestions-heading strong {
  color: var(--ink);
  font-size: var(--type-body,1rem);
  font-weight: 700;
}

.ds-query-suggestions-heading > span {
  flex-shrink: 0;
  color: var(--muted);
  font-size: var(--type-caption,0.75rem);
  font-variant-numeric: tabular-nums;
}

.ds-query-suggestions .ds-query-suggestions-intro {
  margin: 8px 8px 12px;
  color: var(--muted);
  font-size: var(--type-meta,0.8125rem);
  line-height: 1.65;
  overflow-wrap: anywhere;
}

.ds-query-suggestions [cmdk-root] {
  min-width: 0;
}

.ds-query-suggestions [cmdk-list] {
  max-height: min(348px, 48dvh);
  overflow-y: auto;
  overscroll-behavior: contain;
  scroll-padding: 4px;
  scrollbar-width: thin;
  scrollbar-color: var(--selected-edge) transparent;
  outline: none;
}

.ds-query-suggestions [cmdk-list]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  border-radius: 10px;
}

.ds-query-suggestions [cmdk-item] {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 58px;
  padding: 10px;
  border-radius: 10px;
  cursor: pointer;
  user-select: none;
  color: var(--ink);
  transition:
    background 160ms var(--ease),
    color 160ms var(--ease);
}

.ds-query-suggestions [cmdk-item][data-selected="true"] {
  color: var(--accent);
  background: var(--soft);
}

.ds-query-suggestion-icon {
  display: grid;
  place-items: center;
  flex: 0 0 30px;
  height: 30px;
  border-radius: 50%;
  color: var(--accent);
  background: var(--inset);
}

.ds-query-suggestion-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  overflow-wrap: anywhere;
}

.ds-query-suggestion-label {
  font-size: var(--type-ui,0.875rem);
  font-weight: 600;
  line-height: 1.45;
}

.ds-query-suggestion-detail {
  color: var(--muted);
  font-size: var(--type-caption,0.75rem);
  line-height: 1.5;
}

.ds-query-suggestion-enter {
  flex-shrink: 0;
  opacity: 0;
}

.ds-query-suggestions [cmdk-item][data-selected="true"] .ds-query-suggestion-enter {
  opacity: 1;
}

.ds-query-suggestions .ds-query-suggestions-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 82px;
  padding: 16px 10px;
  color: var(--muted);
  font-size: var(--type-ui,0.875rem);
  line-height: 1.6;
}

.ds-query-suggestions .ds-query-suggestions-error {
  flex-wrap: wrap;
  color: var(--danger);
}

.ds-query-suggestions .ds-query-suggestions-state .ds-secondary {
  min-height: 32px;
  padding: 5px 14px;
  border-radius: var(--radius-pill);
  font-size: var(--type-ui,0.875rem);
}

.ds-query-suggestions .ds-query-suggestions-footer {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 14px;
  margin: 8px -8px 0;
  padding: 11px 16px;
  border-top: 1px solid var(--rule);
  color: var(--muted);
  font-size: var(--type-caption,0.75rem);
}

.ds-query-suggestions-footer > span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.ds-query-suggestions .ds-query-suggestions-footer kbd {
  padding: 1px 4px;
  border: 1px solid var(--rule);
  border-radius: 4px;
  background: var(--inset);
  color: var(--muted);
  font-family: inherit;
  font-size: var(--type-caption,0.75rem);
  line-height: 1.5;
}

@media (max-width: 719px) {
  .ds-query-tool .ds-query-help.ds-query-suggestions > summary {
    width: 44px;
    min-width: 44px;
    height: 44px;
    min-height: 44px;
  }

  .ds-query-tool .ds-query-suggestions > .ds-query-suggestions-panel {
    right: -76px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-query-tool .ds-query-help.ds-query-suggestions > summary,
  .ds-query-suggestions [cmdk-item] {
    transition: none;
  }
}

