er-icon:disabled{cursor:not-allowed;opacity:.42;}@media(prefers-reduced-motion:reduce){.ds-reader-icon{transition:none!important;animation:none!important;font-size:var(--type-body,1rem);}}.ds-reader-icon.ds-focus{width:auto;padding:0 12px;gap:6px;border-radius:var(--radius-pill,999px);font-size:var(--type-ui,0.875rem);font-weight:600;}.ds-reader-icon.ds-focus[aria-pressed="true"]{background:var(--soft,#e0f2f8);color:var(--accent,#087293);}@media(max-width:719px){.ds-tabs{height:56px;padding:0 20px;}.ds-tabs button{height:44px;font-size:var(--type-ui,0.875rem);font-weight:600;}.ds-reader-icon{width:44px;height:44px;font-size:var(--type-body,1rem);}.ds-reader-actions{position:relative;right:auto;top:auto;justify-content:flex-end;height:60px;padding:0 20px;}.ds-reader-icon.ds-focus{display:none;font-size:var(--type-ui,0.875rem);font-weight:600;}}.ds-back{display:none;font:inherit;border:0;background:none;color:var(--muted,#566b78);cursor:pointer;}.ds-back:hover{background:var(--inset,#f3f8fb);color:var(--accent,#087293);}.ds-back:focus-visible{outline:2px solid var(--accent,#087293);outline-offset:3px;}@media(max-width:719px){.ds-reader-strip{display:flex;flex-direction:column;font-size:var(--type-body,1rem);}.ds-reader-actions{order:-1;}.ds-back{display:inline-flex;align-items:center;min-height:44px;padding:6px 12px;margin-left:-12px;margin-right:auto;border-radius:var(--radius-pill,999px);font-size:13px;}.ds-reader-icon.ds-close{display:none;}}
.ds-reader-outline {
  position: sticky;
  top: 28px;
  align-self: start;
  box-sizing: border-box;
  width: 170px;
  min-width: 0;
  max-height: var(--reader-outline-available-height, calc(100dvh - 240px));
  padding: 3px 7px 7px 3px;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--rule,#e1eaf0) transparent;
  color: var(--muted,#566b78);
  font-size: 12px;
  line-height: 1.6;
}

.ds-reader-outline-title {
  margin: 0 0 12px 16px;
  color: var(--ink,#1c303b);
  font-size: 12px;
  line-height: 1.5;
  font-weight: 600;
}

.ds-reader-outline-list {
  position: relative;
  list-style: none;
  margin: 0;
  padding: 0;
}

.ds-reader-outline-list::before {
  position: absolute;
  top: 8px;
  bottom: 8px;
  left: 0;
  width: 1px;
  background: var(--rule,#e1eaf0);
  content: "";
}

.ds-reader-outline-item {
  margin: 0;
  padding: 0;
}

.ds-reader-outline-link {
  position: relative;
  display: block;
  width: 100%;
  min-height: 36px;
  margin: 0;
  padding: 8px 4px 8px 16px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--muted,#566b78);
  font-family: inherit;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.65;
  text-align: start;
  white-space: normal;
  overflow-wrap: anywhere;
  cursor: pointer;
  transition: color 160ms var(--ease,cubic-bezier(0.22,1,0.36,1));
}

.ds-reader-outline-link::before {
  position: absolute;
  top: calc(50% - 8px);
  left: 0;
  width: 2px;
  height: 16px;
  border-radius: 1px;
  background: currentColor;
  opacity: 0;
  content: "";
  transition: opacity 160ms var(--ease,cubic-bezier(0.22,1,0.36,1));
}

.ds-reader-outline-link:hover,
.ds-reader-outline-link[aria-current="location"] {
  color: var(--accent,#087293);
}

.ds-reader-outline-link[aria-current="location"]::before {
  opacity: 1;
}

.ds-reader-outline-link:focus-visible {
  outline: 2px solid var(--accent,#087293);
  outline-offset: 1px;
}

@media (prefers-reduced-motion: reduce) {
  .ds-reader-outline-link,
  .ds-reader-outline-link::before {
    transition: none;
  }
}

.ds-reader-outline{font-family:var(--font-ui,"Manrope", "PingFang SC", "Microsoft YaHei UI", "Microsoft YaHei", "Noto Sans CJK SC", "Noto Sans SC", "Segoe UI", sans-serif);font-synthesis:weight;}
